import assert from 'node:assert/strict';
import { compactWindows } from './windows.mjs';
const input=[{service:'api',start:8,end:12},{service:' api ',start:3,end:8},{service:'db',start:2,end:4},{service:'api',start:20,end:22}];
const before=structuredClone(input);
assert.deepEqual(compactWindows(input),[{service:'api',start:3,end:12},{service:'api',start:20,end:22},{service:'db',start:2,end:4}]);
assert.deepEqual(input,before);
console.log('csv1-1-check-passed');

import assert from 'node:assert/strict';
import fs from 'node:fs';
const value=JSON.parse(fs.readFileSync(new URL('./out.json',import.meta.url),'utf8'));
assert.deepEqual(Object.keys(value).sort(),['authority','assignments'].sort());
assert.ok(Array.isArray(value.assignments));
for (const item of value.assignments) assert.deepEqual(Object.keys(item).sort(),['dataset','storage','days'].sort());
console.log('csv1-2-check-passed');

export function drainFair(queues, limit) {
  return { selected: [], remaining: queues };
}

import assert from 'node:assert/strict';
import { drainFair } from './queues.mjs';
const input={beta:['b1'],alpha:['a1','a2'],gamma:['g1','g2']};
const before=structuredClone(input);
assert.deepEqual(drainFair(input,4),{selected:[{tenant:'alpha',job:'a1'},{tenant:'beta',job:'b1'},{tenant:'gamma',job:'g1'},{tenant:'alpha',job:'a2'}],remaining:{alpha:[],beta:[],gamma:['g2']}});
assert.deepEqual(input,before);
console.log('csv1-3-check-passed');
